--
-- Astranaar 'Watch Wind Riders' (map 750 / area 4931): make them patrol instead of hovering.
--
-- The 27 Watch Wind Rider spawns (entry 3634160, guids 16463235-16463261) came across from
-- cata_world as MovementType 0 (IDLE) with no creature_addon row, so they hang motionless in
-- the air over the town. The upstream Cata DB has the identical gap -- retail circles them with
-- server-side splines that were never sniffed -- so nothing was lost in the map 750 import;
-- the movement simply never existed in the source data.
--
-- Two changes:
--
--  1. Drop the 27 duplicate 'Hellscream's Hellion' passengers (entry 3634163, guids
--     16463208-16463234). The sniff recorded the orc rider as its own static creature stacked
--     1.19 yd above its mount, but this DB also carries a vehicle_template_accessory row
--     (3634160 -> 3634163, seat 0), so each wind rider already summons its own seated Hellion.
--     The loose copies are therefore duplicates clipping through the seated ones, and they
--     cannot fly (no creature_template_movement row), so they would be left stranded in mid-air
--     the moment the mounts start moving. Nothing references them: no smart_scripts (by entry
--     or guid), no quest starter/ender, no spawn_group, no pool, no linked_respawn, no
--     creature_addon. The seated accessory rides along with the vehicle for free.
--
--  2. Give each wind rider its own smooth catmullrom orbit (waypoint_data.smoothTransition = 1,
--     no delays, repeating -> seamless loop) centred on its existing spawn point. Per-rider
--     orbits rather than a few shared circles because the 27 spawns are spread over roughly
--     530 x 390 yd at altitudes from z 125 to z 214; one big shared circle would drag riders
--     through the valley walls around Astranaar. Centring each orbit on its own spawn keeps
--     every waypoint within 25 yd horizontally of already-valid airspace and never below the
--     spawn Z (the bob is upward-only, 0 to +5 yd). Radii alternate over 15/17.5/20/22.5/25 yd
--     and direction alternates CW/CCW with a per-rider phase offset so the flight does not look
--     synchronised.
--
-- Note: Creature::CanFly() is true here (creature_template_movement.Flight = 1), so
-- WaypointMovementGenerator calls init.SetFly() and feeds the nodes to MoveSplineInit::MoveTo
-- as raw Vector3 -- no PathGenerator, no navmesh snapping. These creatures cannot get stuck on
-- terrain; the worst case for a badly placed node is visual clipping.
--

-- 1. Remove the duplicate loose Hellscream's Hellion passengers
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 16463208 AND 16463234;
DELETE FROM `creature` WHERE `guid` BETWEEN 16463208 AND 16463234;

-- 2a. Orbit paths: 27 paths x 8 nodes, ids 7501001-7501027
DELETE FROM `waypoint_data` WHERE `id` BETWEEN 7501001 AND 7501027;

-- 2b. Bind each wind rider to its orbit
DELETE FROM `creature_addon` WHERE `guid` IN (16463235, 16463236, 16463237, 16463238, 16463239, 16463240, 16463241, 16463242, 16463243, 16463244, 16463245, 16463246, 16463247, 16463248, 16463249, 16463250, 16463251, 16463252, 16463253, 16463254, 16463255, 16463256, 16463257, 16463258, 16463259, 16463260, 16463261);

-- 2c. IDLE_MOTION_TYPE -> WAYPOINT_MOTION_TYPE
UPDATE `creature` SET `MovementType` = 2 WHERE `guid` IN (16463235, 16463236, 16463237, 16463238, 16463239, 16463240, 16463241, 16463242, 16463243, 16463244, 16463245, 16463246, 16463247, 16463248, 16463249, 16463250, 16463251, 16463252, 16463253, 16463254, 16463255, 16463256, 16463257, 16463258, 16463259, 16463260, 16463261);
